'use strict';
let incidentReport=null,incidentStep='impact';
const incidentMoney=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(n/100);
const incidentAction=(message,fn)=>run(message,fn,'incident-notice');
async function incidentHistory(){const rows=await api('/api/incidents');$('incident-history').innerHTML='<option value="">Choose a saved replay</option>'+rows.map(r=>`<option value="${esc(r.id)}">Seed ${r.seed} · ${esc(r.stage)} · ${r.id.slice(0,10)}</option>`).join('');if(incidentReport)$('incident-history').value=incidentReport.id;}
function incidentRender(){
 const r=incidentReport;if(!r)return;
 const passed=r.verified;
 $('incident-output').innerHTML=`<div class="replay-heading"><div><p class="eyebrow">${r.stage==='candidate'?'REPAIR CANDIDATE':'DELIVERY REPLAY'} · SEED ${r.seed}</p><h3>${passed?'The evidence reconciles.':'The total has a data problem.'}</h3></div><span class="replay-status ${passed?'good':'bad'}">${passed?'Verified against reference':'Not trusted'}</span></div>
 <nav class="replay-steps" aria-label="Incident investigation"><button data-step="impact" aria-pressed="${incidentStep==='impact'}">01 · Follow the impact</button><button data-step="evidence" aria-pressed="${incidentStep==='evidence'}">02 · Inspect the evidence</button><button data-step="repair" aria-pressed="${incidentStep==='repair'}">03 · Test a repair</button></nav>
 <div id="incident-impact" ${incidentStep==='impact'?'':'hidden'}>
 <div class="replay-metrics"><div><span>Trusted reference net</span><strong>${incidentMoney(r.expected.net_cents)}</strong></div><div><span>${r.stage==='candidate'?'Candidate':'Delivered'} net · ${passed?'reconciled':'untrusted'}</span><strong>${incidentMoney(r.observed.net_cents)}</strong></div><div><span>Difference from reference</span><strong class="${r.delta_cents?'status-conflict':'status-matched'}">${incidentMoney(r.delta_cents)}</strong></div></div>
 <p>This is the same synthetic snapshot on both sides, not a comparison of two business days. The delivered total intentionally includes every row to show what an unchecked dashboard would report.</p>
 <div class="replay-lineage" aria-label="Metric dependencies"><button data-source="reference">Trusted ledger<br><small>${r.sources.reference.slice(0,10)}</small></button><span aria-hidden="true">→</span><button data-source="delivered">${r.stage==='candidate'?'Candidate':'Delivered'} payments<br><small>${r.observed.payment_count} records</small></button><span aria-hidden="true">→</span><button id="incident-check-link">Validation + reconciliation<br><small>${r.issues.length} discrepant identities</small></button><span aria-hidden="true">→</span><button id="incident-formula-link">Net revenue<br><small>USD · integer cents</small></button></div>
 <details id="incident-formula"><summary>Show the calculation and refund dependency</summary><p>${incidentMoney(r.observed.gross_cents)} payments − ${incidentMoney(r.observed.refunds_cents)} refunds = ${incidentMoney(r.observed.net_cents)}.</p><p>Reference: ${incidentMoney(r.expected.gross_cents)} − ${incidentMoney(r.expected.refunds_cents)} = ${incidentMoney(r.expected.net_cents)}.</p><button data-source="refunds">Inspect ${r.observed.refund_count} refund records</button><p>${esc(r.definition)}</p></details><div id="incident-source-evidence"></div>
 </div>
 <div id="incident-evidence" ${incidentStep==='evidence'?'':'hidden'}><div class="review-note"><strong>Column/type/key gate: ${r.schema_gate.passed?'PASS':'BLOCKED'}. Reference reconciliation: ${r.issues.length?'FAIL':'PASS'}.</strong><p>A file can pass its schema checks and still omit valid transactions or contain plausible but wrong amounts.</p></div>
 ${r.issues.length?'<p>Each discrepancy links the delivered records to the independently supplied reference. Record 1 is the CSV header.</p>':'<p>Every payment identity and field matches the reference exactly; no duplicate identities remain.</p>'}
 ${r.issues.map(i=>`<details class="replay-issue"><summary><span class="badge">${esc(i.kind)}</span> ${esc(i.payment_id)} · ${i.delivered.length?i.delivered.length+' delivered record(s)':'absent from delivery'}</summary><p>${i.changed_fields.length?'Changed fields: '+esc(i.changed_fields.join(', ')):'Compare the record count and exact values below.'}</p><div class="compare-grid"><div><h4>Reference evidence</h4><pre>${esc(JSON.stringify(i.reference,null,2))}</pre></div><div><h4>Delivered evidence</h4><pre>${esc(JSON.stringify(i.delivered,null,2))}</pre></div></div></details>`).join('')}
 <p class="small">${esc(r.trust)}</p></div>
 <div id="incident-repair" ${incidentStep==='repair'?'':'hidden'}>${r.stage==='delivery'&&r.issues.length?`<h4>Create an isolated candidate</h4><p>Choose identities to replace with their exact reference records. This explicitly restores missing records, replaces differing values, or reconciles duplicate occurrences. It does not silently deduplicate the source.</p><div class="replay-selections">${r.issues.map(i=>`<label><input type="checkbox" name="incident-repair-key" value="${esc(i.payment_id)}"> ${esc(i.payment_id)} · ${esc(i.kind)}</label>`).join('')}</div><button id="incident-select-all">Select all discrepancies</button> <button id="incident-repair-submit" class="primary">Build and verify candidate</button><p class="small">Try repairing only one identity first: unresolved issues must keep the candidate untrusted.</p>`:r.stage==='candidate'?`<h4>${passed?'Candidate passed both checks':'Candidate still has unresolved issues'}</h4><p>${r.changes.length} identity replacement(s); ${r.issues.length} unresolved discrepancy/discrepancies. The original delivery is preserved. This candidate is not published.</p><button id="incident-parent">Return to original delivery</button><details><summary>Exact transformation log · before and after</summary><pre>${esc(JSON.stringify(r.changes,null,2))}</pre></details>`:'<p>No discrepancy to repair. Introduce a failure above to investigate another delivery.</p>'}</div>
 <div class="detail-actions replay-footer"><a class="button" href="/api/incident-bundle/${r.id}" download="incident-${r.id.slice(0,12)}.json">Download evidence bundle</a><span class="small">Run ${r.id.slice(0,12)} · ${esc(r.engine)} · saved locally</span></div><p class="small">${esc(r.limitation)}</p>`;
 $('incident-output').querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>{incidentStep=b.dataset.step;incidentRender();});
 $('incident-check-link').onclick=()=>{incidentStep='evidence';incidentRender();};
 $('incident-formula-link').onclick=()=>{$('incident-formula').open=true;};
 $('incident-output').querySelectorAll('[data-source]').forEach(b=>b.onclick=()=>incidentAction('Opening exact source…',async()=>{const bundle=await api('/api/incident-bundle/'+r.id);const role=b.dataset.source;const file=bundle.files[role];$('incident-source-evidence').innerHTML=`<h4>${esc(role)} source</h4><p class="small">SHA-256 ${esc(file.sha256)}</p><pre>${esc(file.csv)}</pre><a href="/api/dataset-csv/${file.sha256}" download="${role}.csv">Download source CSV</a>`;notice('Source opened without modification.');}));
 if($('incident-select-all'))$('incident-select-all').onclick=()=>$('incident-output').querySelectorAll('[name="incident-repair-key"]').forEach(c=>c.checked=true);
 if($('incident-repair-submit'))$('incident-repair-submit').onclick=()=>incidentAction('Building and independently rechecking candidate…',async()=>{const payment_ids=Array.from($('incident-output').querySelectorAll('[name="incident-repair-key"]:checked'),c=>c.value);if(!payment_ids.length)throw Error('Choose at least one discrepancy.');incidentReport=await api('/api/incident-repair',{incident_id:r.id,payment_ids});incidentStep='repair';incidentRender();await incidentHistory();await refreshDatasets();notice(incidentReport.verified?'Candidate reconciles to the reference. Original delivery is unchanged; no publication occurred.':'Candidate saved, but unresolved discrepancies remain. Inspect the evidence.');});
 if($('incident-parent'))$('incident-parent').onclick=()=>incidentAction('Reopening original delivery…',async()=>{incidentReport=await api('/api/incident/'+r.parent);incidentStep='repair';incidentRender();await incidentHistory();notice('Original delivery reopened.');});
}
$('incident-start').onclick=()=>incidentAction('Replaying a synthetic delivery…',async()=>{const faults=Array.from(document.querySelectorAll('[name="incident-fault"]:checked'),c=>c.value);incidentReport=await api('/api/incident-simulate',{seed:Number($('incident-seed').value),faults});incidentStep='impact';incidentRender();await incidentHistory();await refreshDatasets();notice('Replay saved. Follow the total into its source records. No external service was called.');});
$('incident-history').onchange=()=>incidentAction('Reopening saved replay…',async()=>{if(!$('incident-history').value)return;incidentReport=await api('/api/incident/'+$('incident-history').value);incidentStep='impact';incidentRender();notice('Saved replay opened unchanged.');});
incidentHistory().catch(e=>{$('incident-notice').textContent=e.message;});
